join public.source_families f on f.source_id = (select id from public.reference_sources where external_id = $check_c1d8a0fd0ea191c9$"togo-reference-prices-2026-01"$check_c1d8a0fd0ea191c9$::jsonb #>> '{}') and f.external_id = x.family_id
on conflict (source_id, external_id) do nothing;
commit;
